  /* Source × bias-dimension matrix, standardised (0 = corpus mean, in SDs).
   * → { rows:[sourceId], cols:[dimId], cells:[{row,col,value,n}] } */
  function biasHeat(eventId) {
    return memo('bias:' + eventId, function () {
      // Deliberate signatures: tabloids high on intensifiers and metaphor, the
      // wire near zero everywhere, the partisan outlet high on distancing.
      var profile = {
        boreal:    { epi: -0.28, inten: -0.35, attrib: -0.42, agency: -0.10, dist: -0.30, metaph: 0.22 },
        depeche:   { epi: 0.12,  inten: 0.05,  attrib: 0.18,  agency: 0.24,  dist: -0.05, metaph: 0.35 },
        herald:    { epi: 0.05,  inten: -0.12, attrib: 0.22,  agency: 0.30,  dist: 0.02,  metaph: 0.28 },
        matin:     { epi: 0.62,  inten: 0.94,  attrib: 0.58,  agency: 0.36,  dist: 0.55,  metaph: 1.05 },
        foothills: { epi: 0.55,  inten: 0.88,  attrib: 0.44,  agency: 0.41,  dist: 0.48,  metaph: 0.96 },
        westwire:  { epi: -0.15, inten: 0.30,  attrib: -0.26, agency: -0.32, dist: 0.10,  metaph: 0.05 },
        fil:       { epi: -0.52, inten: -0.61, attrib: -0.55, agency: -0.18, dist: -0.58, metaph: -0.48 },
        signal:    { epi: 0.88,  inten: 1.12,  attrib: 0.96,  agency: 0.72,  dist: 1.28,  metaph: 0.84 }
      };
      var shift = eventId === 'ab' ? 0.12 : 0;
      var cells = [];
      E.sources.forEach(function (s) {
        E.biasDims.forEach(function (d) {
          var r = G.rng('bh' + eventId + s.id + d.id);
          cells.push({
            row: s.id, col: d.id,
            value: G.round(profile[s.id][d.id] + shift * (d.id === 'metaph' ? 1 : 0.3) + 0.10 * G.gauss(r), 2),
            n: Math.round(600 + 2400 * r())
          });
        });
      });
      return {
        rows: E.sources.map(function (s) { return { id: s.id, label: s.name, meta: s.kind }; }),
        cols: E.biasDims.map(function (d) { return { id: d.id, label: d.name, gloss: d.gloss }; }),
        cells: cells
      };
    });
  }

  /* Coded press photographs. → [{id,actor,source,angle,shot,expr,set,congruence}] */
  function imageCodes() {
    return memo('img', function () {
      var out = [];
      var actors = [{ id: 'cn', label: 'Marchand (CN)' }, { id: 'ms', label: 'Ouellet (MS)' },
                    { id: 'yes', label: 'Yes camp' }, { id: 'no', label: 'No camp' }];
      var srcs = ['boreal', 'depeche', 'matin', 'foothills', 'westwire', 'signal'];
      // Favourability tilt per (source, actor): drives angle/expression choices.
      var fav = {
        boreal:    { cn: 0.02, ms: 0.10, yes: -0.04, no: 0.04 },
        depeche:   { cn: 0.22, ms: -0.18, yes: -0.10, no: 0.14 },
        matin:     { cn: 0.34, ms: -0.44, yes: 0.06, no: -0.02 },
        foothills: { cn: 0.04, ms: -0.20, yes: 0.46, no: -0.32 },
        westwire:  { cn: -0.06, ms: 0.14, yes: 0.08, no: 0.02 },
        signal:    { cn: 0.30, ms: -0.62, yes: 0.58, no: -0.40 }
      };
      srcs.forEach(function (s) {
        actors.forEach(function (a) {
          for (var k = 0; k < 3; k++) {
            var r = G.rng('im' + s + a.id + k);
            var f = fav[s][a.id] + 0.18 * G.gauss(r);
            out.push({
              id: s + '-' + a.id + '-' + k,
              source: s, actor: a.id, actorLabel: a.label,
              angle: f > 0.18 ? 'Low (looking up)' : f < -0.14 ? 'High (looking down)' : 'Eye level',
              shot: r() > 0.62 ? 'Close-up' : r() > 0.3 ? 'Medium' : 'Wide',
              expr: f > 0.12 ? 'Positive' : f < -0.12 ? 'Negative' : 'Neutral',
              set: ['Podium', 'Crowd', 'Candid', 'Institutional'][Math.floor(r() * 4)],
              favour: G.round(f, 2),
              // −1 caption contradicts the image, +1 caption reinforces it
              congruence: G.round(G.clamp(f * 0.8 + 0.3 * G.gauss(r), -1, 1), 2)
            });
          }
        });
      });
      return out;
    });
  }

  /* Image–caption relationship, as a diverging distribution per source.
   * → { categories:[...], rows:[{id,label,values:[...]}] } */
  function captionCongruence() {
    var imgs = imageCodes();
    var cats = ['Caption contradicts image', 'Caption is neutral', 'Caption reinforces image'];
    var by = {};
    imgs.forEach(function (d) {
      by[d.source] = by[d.source] || [0, 0, 0];
      by[d.source][d.congruence < -0.15 ? 0 : d.congruence > 0.15 ? 2 : 1]++;
    });
    return {
      categories: cats,
      centreIndex: 1,
      rows: Object.keys(by).map(function (s) {
        var t = G.sum(by[s]);
        return { id: s, label: E.sourceById[s].name, values: by[s].map(function (v) { return G.round(v / t, 3); }) };
      })
    };
  }

  /* ================================================================
   * RQ3 — messages from actors to coverage
   * ================================================================ */

  /* Three-stage flow with adjacent links only: every message issued by a
   * campaign goes down a channel, and is then either reported or not.
   * Ribbons keep the originating theme's colour across both hops.
   * → { stages, nodes:[{id,stage,label,value,slot}], links:[{source,target,value,slot}], legend } */
  function messageFlow(eventId) {
    return memo('flow:' + eventId, function () {
      var frames = eventId === 'qc'
        ? [{ id: 'cost', label: 'Cost of living', slot: 1 }, { id: 'health', label: 'Health care', slot: 2 },
           { id: 'imm', label: 'Immigration & language', slot: 3 }, { id: 'ident', label: 'Identity & secularism', slot: 4 },
           { id: 'climate', label: 'Climate & energy', slot: 5 }, { id: 'other', label: 'Everything else', slot: 7 }]
        : [{ id: 'sov', label: 'Sovereignty', slot: 1 }, { id: 'energy', label: 'Energy & pipelines', slot: 2 },
           { id: 'fiscal', label: 'Equalisation', slot: 3 }, { id: 'treaty', label: 'Treaty rights', slot: 4 },
           { id: 'health', label: 'Health care', slot: 5 }, { id: 'other', label: 'Everything else', slot: 7 }];

      var issued  = eventId === 'qc' ? [820, 640, 510, 300, 380, 700] : [910, 700, 560, 240, 330, 620];
      var adRate  = eventId === 'qc' ? [0.42, 0.30, 0.55, 0.61, 0.18, 0.12] : [0.58, 0.52, 0.47, 0.11, 0.21, 0.10];
      // Uptake is higher for ad-backed messages, but the gap varies by theme.
      var upPaid  = eventId === 'qc' ? [0.44, 0.52, 0.71, 0.78, 0.30, 0.22] : [0.74, 0.55, 0.49, 0.41, 0.34, 0.20];
      var upOrg   = eventId === 'qc' ? [0.25, 0.34, 0.47, 0.51, 0.16, 0.11] : [0.58, 0.36, 0.29, 0.22, 0.19, 0.09];

      var nodes = [], links = [];
      var tot = { paid: 0, organic: 0, reported: 0, unreported: 0 };

      frames.forEach(function (f, i) {
        var paid = Math.round(issued[i] * adRate[i]);
        var org = issued[i] - paid;
        var repP = Math.round(paid * upPaid[i]), repO = Math.round(org * upOrg[i]);

        nodes.push({ id: 'f-' + f.id, stage: 0, label: f.label, value: issued[i], slot: f.slot });
        links.push({ source: 'f-' + f.id, target: 'paid', value: paid, slot: f.slot, label: f.label });
        links.push({ source: 'f-' + f.id, target: 'organic', value: org, slot: f.slot, label: f.label });
        links.push({ source: 'paid', target: 'reported', value: repP, slot: f.slot, label: f.label });
        links.push({ source: 'paid', target: 'unreported', value: paid - repP, slot: f.slot, label: f.label });
        links.push({ source: 'organic', target: 'reported', value: repO, slot: f.slot, label: f.label });
        links.push({ source: 'organic', target: 'unreported', value: org - repO, slot: f.slot, label: f.label });

        tot.paid += paid; tot.organic += org;
        tot.reported += repP + repO; tot.unreported += (paid - repP) + (org - repO);
      });

      nodes.push({ id: 'paid', stage: 1, label: 'Backed by ad spend', value: tot.paid });
      nodes.push({ id: 'organic', stage: 1, label: 'Organic only', value: tot.organic });
      nodes.push({ id: 'reported', stage: 2, label: 'Reported in news', value: tot.reported });
      nodes.push({ id: 'unreported', stage: 2, label: 'Never reported', value: tot.unreported });

      return {
        stages: ['Messages issued', 'How they were pushed', 'What happened next'],
        nodes: nodes, links: links,
        legend: frames.map(function (f) { return { slot: f.slot, label: f.label }; }),
        totals: tot
      };
    });
  }

