  /* Accounts and outlets, linked by sharing. → { nodes:[...], links:[...] } */
  function ampNetwork() {
    return memo('net', function () {
      var nodes = [], links = [];
      // Three communities, deliberately: pro-Yes/right-leaning, pro-No/left-leaning, institutional.
      var comms = [
        { id: 'c1', label: 'Sovereignty-aligned cluster', slot: 2 },
        { id: 'c2', label: 'Federalist-aligned cluster', slot: 1 },
        { id: 'c3', label: 'Institutional & civic cluster', slot: 3 }
      ];
      E.sources.forEach(function (s) {
        var c = { boreal: 'c3', fil: 'c3', depeche: 'c3', herald: 'c3', westwire: 'c3',
                  matin: 'c1', foothills: 'c1', signal: 'c1' }[s.id];
        nodes.push({ id: 'src-' + s.id, label: s.short, type: 'outlet', comm: c, size: 26 });
      });
      var names = ['@prairie_watch', '@le_fil_rouge', '@AB_sovereignty', '@QC_verified', '@energy_first',
                   '@treaty_now', '@citycouncilAB', '@campaign_decoder', '@northwind', '@reveil_qc',
                   '@fact_check_ca', '@foothills_dad', '@laurentienne', '@pipeline_pete', '@la_releve',
                   '@calgary_renter', '@quebec_reader', '@westernvoice', '@solidarite_mtl', '@budgethawk',
                   '@boreal_listener', '@albertafirst_', '@montrealer_', '@ruralvoice_ab'];
      names.forEach(function (n, i) {
        var r = G.rng('acct' + n);
        var c = comms[i % 3].id;
        nodes.push({
          id: n, label: n, type: 'account', comm: c,
          size: 6 + Math.pow(r(), 2) * 26,
          followers: Math.round(2000 * Math.pow(10, 1 + 2.2 * r())),
          reshares: Math.round(40 + 900 * Math.pow(r(), 1.8))
        });
      });
      // Accounts share mostly within their community, sometimes across.
      nodes.filter(function (d) { return d.type === 'account'; }).forEach(function (a) {
        var r = G.rng('lnk' + a.id);
        var outlets = nodes.filter(function (d) { return d.type === 'outlet'; });
        var k = 2 + Math.floor(r() * 3);
        for (var j = 0; j < k; j++) {
          var pool = outlets.filter(function (o) { return r() < 0.75 ? o.comm === a.comm : true; });
          var t = pool[Math.floor(r() * pool.length)];
          if (t) links.push({ source: a.id, target: t.id, value: 1 + Math.floor(r() * 6) });
        }
      });
      return { nodes: nodes, links: links, communities: comms };
    });
  }

  /* Post-level linguistic bias vs engagement. → [{id,bias,engagement,comm,source,text}] */
  function biasEngagement() {
    return memo('be', function () {
      var out = [];
      var comms = ['c1', 'c2', 'c3'];
      for (var i = 0; i < 260; i++) {
        var r = G.rng('be' + i);
        var comm = comms[Math.floor(r() * 3)];
        var bias = G.clamp(0.9 * r() + 0.35 * G.gauss(r) + (comm === 'c3' ? -0.35 : 0.15), -0.4, 2.4);
        // Positive association, plus heavy-tailed noise — engagement is log-scaled.
        var eng = Math.exp(1.6 + 0.62 * bias + 0.55 * G.gauss(r));
        out.push({
          id: 'p' + i, bias: G.round(bias, 3), engagement: G.round(eng, 2), comm: comm,
          source: E.sources[Math.floor(r() * E.sources.length)].id,
          replies: Math.round(eng * (3 + 8 * r()))
        });
      }
      return out;
    });
  }

