  /* ================================================================
   * RQ5 — coverage, polls and markets
   * ================================================================ */

  /* Polling estimates with uncertainty, plus daily coverage volume.
   * → { days, series:[{id,label,slot,values,lo,hi}], volume:[...], events:[{i,label,note}] } */
  function polls(eventId) {
    return memo('polls:' + eventId, function () {
      var defs = eventId === 'qc'
        ? [{ id: 'cn', label: 'Coalition Nationale', slot: 1, start: 34, end: 31 },
           { id: 'pld', label: 'Parti Libéral-Démocrate', slot: 2, start: 25, end: 29 },
           { id: 'ms', label: 'Mouvement Solidaire', slot: 3, start: 19, end: 21 },
           { id: 'av', label: 'Alliance Verte', slot: 4, start: 12, end: 10 },
           { id: 'pr', label: 'Parti de la Relance', slot: 5, start: 10, end: 9 }]
        : [{ id: 'yes', label: 'Yes', slot: 2, start: 44, end: 49 },
           { id: 'no', label: 'No', slot: 1, start: 47, end: 44 },
           { id: 'und', label: 'Undecided', slot: 7, start: 9, end: 7 }];

      var series = defs.map(function (d) {
        var path = G.range(DAYS).map(function (i) { return d.start + (d.end - d.start) * (i / (DAYS - 1)); });
        var noise = G.smooth(G.walk(DAYS, { seed: 'poll' + eventId + d.id, start: 0, mean: 0, vol: 0.9, pull: 0.22 }), 2);
        var vals = path.map(function (v, i) { return G.round(v + noise[i], 1); });
        return {
          id: d.id, label: d.label, slot: d.slot,
          values: vals,
          lo: vals.map(function (v) { return G.round(v - 2.6, 1); }),
          hi: vals.map(function (v) { return G.round(v + 2.6, 1); })
        };
      });

      var volBase = G.walk(DAYS, { seed: 'vol' + eventId, start: 1, mean: 1, vol: 0.10, pull: 0.3, min: 0.5 });
      var volume = G.range(DAYS).map(function (i) {
        var b = 1 + G.bump(DAYS, 17, 2.2, 0.8)[i] + G.bump(DAYS, 23, 1.8, 1.1)[i] + (i > 34 ? (i - 34) * 0.14 : 0);
        return Math.round(340 * volBase[i] * b);
      });

      var evs = eventId === 'qc'
        ? [{ i: 8, label: 'Platform launches' }, { i: 17, label: 'Costing controversy' },
           { i: 23, label: 'Leaders’ debate' }, { i: 34, label: 'Final week' }, { i: 40, label: 'Election day' }]
        : [{ i: 8, label: 'Campaign registration closes' }, { i: 17, label: 'Court reference opinion' },
           { i: 23, label: 'Televised forum' }, { i: 34, label: 'Final week' }, { i: 40, label: 'Referendum day' }];

      return {
        days: G.range(DAYS).map(function (i) { return { i: i, label: E.dayLabel(i) }; }),
        series: series, volume: volume, events: evs
      };
    });
  }

  /* Cross-correlation of coverage tone with polling change, lag −14…+14.
   * Negative lag = coverage moves first. → [{lag,value,ci}] */
  function lagCorrelation(eventId) {
    return memo('lag:' + eventId, function () {
      var peak = eventId === 'qc' ? -3 : -2;
      return G.range(29).map(function (k) {
        var lag = k - 14;
        var r = G.rng('lc' + eventId + lag);
        var v = 0.34 * Math.exp(-Math.pow((lag - peak) / 4.2, 2)) - 0.05 + 0.035 * G.gauss(r);
        return { lag: lag, value: G.round(v, 3), ci: 0.11 };
      });
    });
  }

  /* Prediction-market price around the five biggest coverage shocks.
   * → { window:[-5..+10], series:[{id,label,slot,values}] } */
  function eventStudy(eventId) {
    return memo('es:' + eventId, function () {
      var shocks = eventId === 'qc'
        ? [{ id: 'k1', label: 'Costing controversy (day 17)', slot: 1, jump: -4.2 },
           { id: 'k2', label: 'Debate (day 23)', slot: 2, jump: 3.1 },
           { id: 'k3', label: 'Endorsement wave (day 29)', slot: 3, jump: 1.4 },
           { id: 'k4', label: 'Final-week ad blitz (day 35)', slot: 4, jump: 0.6 }]
        : [{ id: 'k1', label: 'Court opinion (day 17)', slot: 1, jump: 5.6 },
           { id: 'k2', label: 'Televised forum (day 23)', slot: 2, jump: -2.4 },
           { id: 'k3', label: 'Turnout projection (day 30)', slot: 3, jump: 2.0 },
           { id: 'k4', label: 'Final-week ad blitz (day 35)', slot: 4, jump: 0.9 }];
      var win = G.range(16).map(function (i) { return i - 5; });
      return {
        window: win,
        series: shocks.map(function (s) {
          var r = G.rng('es' + eventId + s.id);
          return {
            id: s.id, label: s.label, slot: s.slot,
            values: win.map(function (t) {
              var base = t < 0 ? 0 : s.jump * (1 - Math.exp(-t / 2.1));
              return G.round(base + 0.45 * G.gauss(r), 2);
            })
          };
        })
      };
    });
  }

